// Generated by EldUI from the design file — deterministic export (no AI).
import { createRouter, createWebHistory, type RouteRecordRaw } from 'vue-router'
import { produtos } from '../cms/produtos'

declare module 'vue-router' {
  interface RouteMeta {
    title?: string
    description?: string
    lang?: string
    noindex?: boolean
  }
}

const routes: RouteRecordRaw[] = [
  {
    path: '/',
    component: () => import('../layouts/GlobalLayout.vue'),
    children: [
      {
        path: '/',
        name: 'HomepageView',
        component: () => import('../views/HomepageView.vue'),
        meta: { title: 'Laura&Ponto', lang: 'pt-BR' },
      },
      {
        path: '/aulas-de-croche',
        name: 'AulasDeCrocheView',
        component: () => import('../views/AulasDeCrocheView.vue'),
        meta: { title: 'Aulas de crochê' },
      },
      {
        path: '/vale-presentes',
        name: 'ValePresentesView',
        component: () => import('../views/ValePresentesView.vue'),
        meta: { title: 'Vale presentes' },
      },
      {
        path: '/receitas',
        name: 'ReceitasView',
        component: () => import('../views/ReceitasView.vue'),
        meta: { title: 'Receitas' },
      },
      {
        path: '/produtos',
        name: 'GaleriaDeProdutosView',
        component: () => import('../views/GaleriaDeProdutosView.vue'),
        meta: { title: 'Produtos' },
      },
      {
        path: '/produtos/produtos/:slug',
        name: 'PaginaDeDetalhesDoProdutoView',
        component: () => import('../views/PaginaDeDetalhesDoProdutoView.vue'),
        beforeEnter: (to) => {
          const item = produtos.find((x) => x.slug === to.params.slug)
          if (!item) return { name: 'NotFound', params: { pathMatch: to.path.slice(1).split('/') } }
          to.meta.title = ``
          to.meta.description = ``
        },
      },
      {
        path: '/produtos/chaveiros',
        name: 'GaleriaDeChaveirosView',
        component: () => import('../views/GaleriaDeChaveirosView.vue'),
        meta: { title: 'Chaveiros' },
      },
      {
        path: '/produtos/chaveiros/totoro',
        name: 'PaginaDeDetalhesDoProdutoView2',
        component: () => import('../views/PaginaDeDetalhesDoProdutoView.vue'),
        meta: { title: 'Página de Detalhes do Produto' },
      },
      {
        path: '/monte-o-seu',
        name: 'MonteOSeuView',
        component: () => import('../views/MonteOSeuView.vue'),
        meta: { title: 'Monte o seu' },
      },
      {
        path: '/login',
        name: 'LoginView',
        component: () => import('../views/LoginView.vue'),
        meta: { title: 'Login' },
      },
      {
        path: '/sacola',
        name: 'SacolaView',
        component: () => import('../views/SacolaView.vue'),
        meta: { title: 'Sacola' },
      },
      {
        path: '/:pathMatch(.*)*',
        name: 'NotFound2',
        component: () => import('../views/Erro404View.vue'),
        meta: { title: 'Página não encontrada' },
      },
    ],
  },
]

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes,
  scrollBehavior: () => ({ top: 0 }),
})

/** Project settings used by every page. */
const SITE = {
  name: 'Laura&Ponto',
  titleTemplate: '%s | Laura&Ponto',
  description: 'Fazemos amigurumis e artigos personalizados em crochê. Peças feitas à mão, sob encomenda e à pronta-entrega.',
  lang: 'pt-BR',
  url: '',
}

function setMeta(selector: string, create: () => HTMLElement, attr: string, value: string | null) {
  let tag = document.head.querySelector<HTMLElement>(selector)
  if (!value) return tag?.remove()
  if (!tag) document.head.appendChild((tag = create()))
  tag.setAttribute(attr, value)
}

// page metadata: title, description, language, canonical URL, robots
router.afterEach((to) => {
  const title = to.meta.title ? SITE.titleTemplate.replace('%s', to.meta.title) : SITE.name
  if (title) document.title = title
  document.documentElement.lang = to.meta.lang || SITE.lang
  const meta = (name: string) => () => Object.assign(document.createElement('meta'), { name })
  setMeta('meta[name="description"]', meta('description'), 'content', to.meta.description || SITE.description || null)
  setMeta('meta[name="robots"]', meta('robots'), 'content', to.meta.noindex ? 'noindex' : null)
  setMeta('link[rel="canonical"]', () => Object.assign(document.createElement('link'), { rel: 'canonical' }), 'href', SITE.url ? SITE.url + router.resolve(to.fullPath).href : null)
})

export default router
